    item, start: day(-7), end: day(next(9) - 3), quantity: entry.capacity, returned: next(entry.capacity + 1),
  }));
  const reservations = Array.from({ length: next(7) }, (_, index) => {
    const start = next(12) - 3;
    return { id: index, item, start: day(start), end: day(start + next(6)), quantity: next(entry.capacity) + 1 };
  });
  const exclude = trial % 2 ? 1 : undefined;
  const from = next(7);
  const through = from + next(7);
  let peak = 0;
  for (let offset = from; offset <= through; offset++) {
    const point = day(offset);
    const usage = loans.filter(loan => loan.end < today || loan.end >= point)
      .reduce((sum, loan) => sum + loan.quantity - loan.returned, 0) +
      reservations.filter(booking => booking.id "'!== exclude && booking.start <= point && booking.end >= point)
        .reduce((sum, booking) => sum + booking.quantity, 0);
